text:
{
 "summary": {
  "es": "国会議員《こっかいぎいん》の仕事《しごと》と、受《う》けとるお金《かね》などをまとめます。歳費《さいひ》（給料《きゅうりょう》のこと）は毎月《まいつき》129万《まん》4千《せん》円《えん》、調査《ちょうさ》研究《けんきゅう》広報《こうほう》滞在費《たいざいひ》（活動《かつどう》のためのお金《かね》）は毎月《まいつき》100万《まん》円《えん》です。議員《ぎいん》の立場《たちば》を守《まも》るしくみ（身分保障《みぶんほしょう》）もまとめます。",
  "hs": "国会議員の職務と、歳費《さいひ》（月額129万《まん》4千《せん》円）・調査研究広報｜滞在費《たいざいひ》（月額100万《まん》円）などの待遇《たいぐう》、身分保障（議員の立場を守るしくみ）を整理します。"
 },
 "blocks/0/text": {
  "es": "国会議員《こっかいぎいん》の歳費《さいひ》や手当《てあて》の金額《きんがく》は、どの法律《ほうりつ》で決《き》まっているのでしょう？",
  "hs": "国会議員の歳費《さいひ》や手当の額は、どの法律で決まっているのでしょう？"
 },
 "blocks/1/items/0": {
  "es": "本会議《ほんかいぎ》や委員会《いいんかい》で話《はな》し合《あ》い、決《き》めることに加《くわ》わる",
  "hs": "本会議・委員会での審議《しんぎ》と意思決定への参加"
 },
 "blocks/1/items/1": {
  "es": "法律《ほうりつ》の案《あん》や決議《けつぎ》の案《あん》などを出《だ》す（発議《はつぎ》）",
  "hs": "法律案や決議案などの議案の発議（提出すること）"
 },
 "blocks/1/items/2": {
  "es": "内閣《ないかく》に、文書《ぶんしょ》で質問《しつもん》する（質問主意書《しつもんしゅいしょ》を出《だ》す）",
  "hs": "内閣に対する質問主意書（文書での質問）の提出"
 },
 "blocks/1/items/3": {
  "es": "国民《こくみん》からのお願《ねが》い（請願《せいがん》）を、国会《こっかい》に紹介《しょうかい》する",
  "hs": "国民からの請願《せいがん》（国会へのお願い）の紹介《しょうかい》"
 },
 "blocks/3/text": {
  "es": "調査《ちょうさ》研究《けんきゅう》広報《こうほう》滞在費《たいざいひ》のきまりは、令和《れいわ》6年《ねん》法律《ほうりつ》第《だい》81号《ごう》で変《か》わりました（令和《れいわ》7年《ねん》8月《がつ》1日《ついたち》から）。年《ねん》に1回《かい》、何《なん》に使《つか》ったかの報告書《ほうこくしょ》を、議長《ぎちょう》に出《だ》すことになりました。そのとき、領収書《りょうしゅうしょ》などの写《うつ》しもいっしょに出《だ》します。報告書《ほうこくしょ》は、みんなが見《み》られるようにします。使《つか》わずに残《のこ》ったお金《かね》は、返《かえ》すことになりました。",
  "hs": "調査研究広報｜滞在費《たいざいひ》は、令和6年法律第81号による改正（令和7年8月1日｜施行《しこう》）で、年1回、使い道の報告書を領収書などの写しとともに議長に提出して公開すること、残ったお金を返還《へんかん》することが定められました。"
 },
 "blocks/4/text": {
  "es": "議員《ぎいん》は、法律《ほうりつ》で決《き》められた場合《ばあい》をのぞいて、国会《こっかい》が開《ひら》かれている間《あいだ》（会期《かいき》中《ちゅう》）はつかまりません（不逮捕特権《ふたいほとっけん》、第《だい》50条《じょう》）。また、議院《ぎいん》で行《おこな》った演説《えんぜつ》・討論《とうろん》・表決《ひょうけつ》（賛成《さんせい》か反対《はんたい》かを決《き》めること）について、議院《ぎいん》の外《そと》で責任《せきにん》を問《と》われません（免責特権《めんせきとっけん》、第《だい》51条《じょう》）。",
  "hs": "議員は、法律の定める場合を除いて国会の会期中は逮捕《たいほ》されず（不逮捕特権《ふたいほとっけん》、第50条）、議院で行った演説・討論・表決について院外で責任を問われません（免責特権《めんせきとっけん》、第51条）。"
 }
}
